theorySlides.codeSnippet:
.grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr; /* 3 equal cols */
  grid-template-rows: 100px 200px;    /* 2 rows */
  gap: 20px;                          /* spacing */
}

.grid {
  /* Fixed pixels */
  grid-template-columns: 200px 200px;

  /* Fractional units (proportional) */
  grid-template-columns: 1fr 2fr;  /* 1:2 ratio */

  /* Repeat function */
  grid-template-columns: repeat(3, 1fr);
}

.item {
  grid-column: 1 / 3;  /* span cols 1-2 */
  grid-row: 1 / 2;     /* row 1 only */

  /* Shorthand */
  grid-area: 1 / 1 / 2 / 3;
}

/* Default styles for mobile */
.container {
  width: 100%;
}

/* Styles for tablets and up */
@media (min-width: 768px) {
  .container {
    width: 750px;
  }
}

/* Styles for desktop */
@media (min-width: 1200px) {
  .container {
    width: 1140px;
  }
}

/* Mobile-first: single column */
.grid {
  display: flex;
  flex-direction: column;
}

/* Tablet: 2 columns */
@media (min-width: 768px) {
  .grid {
    flex-direction: row;
    flex-wrap: wrap;
  }
  .item { width: 50%; }
}

.button {
  background: blue;
  transition: background 0.3s ease;
}

.button:hover {
  background: darkblue;
}

/* Multiple properties */
.card {
  transition: transform 0.3s, box-shadow 0.3s;
}

.card:hover {
  transform: translateY(-5px);
  box-shadow: 0 10px 20px rgba(0,0,0,0.2);
}

@keyframes pulse {
  0% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.1);
  }
  100% {
    transform: scale(1);
  }
}

.heart {
  animation: pulse 1s infinite;
}

.element {
  animation-name: slide-in;
  animation-duration: 0.5s;
  animation-timing-function: ease-out;
  animation-delay: 0.2s;
  animation-iteration-count: 1;
  animation-fill-mode: forwards;

  /* Shorthand */
  animation: slide-in 0.5s ease-out 0.2s forwards;
}

